<?php require 'config/config.php';require_role(['store']);$page_title='Stock movements';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$pid=(int)$_POST['product_id'];$qty=(float)$_POST['quantity'];$type=$_POST['movement_type'];$delta=$type==='in'?$qty:-$qty;$pdo->beginTransaction();try{$s=$pdo->prepare('UPDATE products SET quantity=quantity+? WHERE id=? AND quantity+?>=0');$s->execute([$delta,$pid,$delta]);if(!$s->rowCount())throw new Exception('Insufficient stock or invalid product.');$s=$pdo->prepare('INSERT INTO stock_movements(product_id,movement_type,quantity,reference,notes,created_by) VALUES(?,?,?,?,?,?)');$s->execute([$pid,$type,$qty,$_POST['reference'],$_POST['notes'],user()['id']]);$pdo->commit();log_action('Stock movement',$type.' '.$qty.' product '.$pid);$msg='Stock movement recorded.';}catch(Throwable $e){$pdo->rollBack();$msg=$e->getMessage();}}$products=$pdo->query('SELECT id,name,unit FROM products ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT m.*,p.name,p.unit,u.name staff FROM stock_movements m JOIN products p ON p.id=m.product_id JOIN users u ON u.id=m.created_by ORDER BY m.id DESC LIMIT 100')->fetchAll();require 'includes/header.php';?><h1>Stock movements</h1><?php if($msg):?><div class="alert"><?=$msg?></div><?php endif;?><div class="panel"><form method="post"><?php csrf_field();?><div class="formgrid"><div><label>Product</label><select name="product_id"><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'].' ('.$p['unit'].')')?></option><?php endforeach;?></select></div><div><label>Movement</label><select name="movement_type"><option value="in">Stock received</option><option value="out">Stock issued</option></select></div><div><label>Quantity</label><input type="number" min="0.01" step="0.01" name="quantity" required></div><div><label>Reference</label><input name="reference"></div><div><label>Notes</label><input name="notes"></div></div><p><button>Record movement</button></p></form></div><div class="panel"><h2>Movement history</h2><div class="tablewrap"><table><tr><th>Date</th><th>Product</th><th>Type</th><th>Quantity</th><th>Reference</th><th>Recorded by</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['name'])?></td><td><?=e($r['movement_type'])?></td><td><?=e($r['quantity'].' '.$r['unit'])?></td><td><?=e($r['reference'])?></td><td><?=e($r['staff'])?></td></tr><?php endforeach;?></table></div></div><?php require 'includes/footer.php';?>